window.SAOMD_STORIES[410401201]={"id":410401201,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410401201:1:1","speaker":"Eugeo","text":"Kirito! Asuna!","pose":10530201,"background":"bg_event_alne_field_christmas","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"桐人！ 亚丝娜！"}]},{"id":2,"order":2,"actions":[{"uid":"410401201:2:1","speaker":"Kirito","text":"Eugeo? What's the problem?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧？有什么问题吗？"},{"uid":"410401201:2:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:2:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":3,"order":3,"actions":[{"uid":"410401201:3:1","speaker":"Eugeo","text":"Enemies, from behind us! Those\nmonsters from earlier formed a\nherd and are coming this way!","pose":105302012,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"敌人，从我们身后来了！刚才那些怪物成群结队，朝这边过来了！"}]},{"id":4,"order":4,"actions":[{"uid":"410401201:4:1","speaker":"Kirito","text":"Gah! These things just don't\nlearn! Come on, Asuna!\nIt's fighting time!","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊啊！这些东西根本学不来！加油，亚丝娜！战斗时间到了！"},{"uid":"410401201:4:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:4:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410401201:5:1","speaker":"Asuna","text":"You got it!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你懂了！"}]},{"id":6,"order":6,"actions":[{"uid":"410401201:6:1","speaker":"Seven","text":"Hold it!","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"坚持住！"}]},{"id":7,"order":7,"actions":[{"uid":"410401201:7:1","speaker":"Kirito","text":"Seven?!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"赛玟？！"}]},{"id":8,"order":8,"actions":[{"uid":"410401201:8:1","speaker":"Seven","text":"You think our carols might hurt\nthese monsters, right?","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你觉得我们的颂歌可能会伤害这些怪物吧？"}]},{"id":9,"order":9,"actions":[{"uid":"410401201:9:1","speaker":"Seven","text":"So... Want to conduct a little\nhands-on experiment?","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"那么……想要进行一些动手实验吗？"}]},{"id":10,"order":10,"actions":[{"uid":"410401201:10:1","speaker":"Kirito","text":"Oh, that's a great idea!\nIt just might work!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"噢，真是个好主意！它可能会起作用！"}]},{"id":11,"order":11,"actions":[{"uid":"410401201:11:1","speaker":"Asuna","text":"But then we'll have to put those\ncarolers on the front lines...\nCan they handle it?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是这样我们就得把那些颂歌者放到前线了……他们能应付吗？"}]},{"id":12,"order":12,"actions":[{"uid":"410401201:12:1","speaker":"Seven","text":"Pfft, they'll be fine! Besides,\neveryone's pretty stressed\nout over all this.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"噗，他们不会有事的！此外，每个人都对这一切感到压力很大。"}]},{"id":13,"order":13,"actions":[{"uid":"410401201:13:1","speaker":"Seven","text":"They need to work off some steam!\nBesides, you guys will be there in\na pinch, right?","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"他们需要发泄一下！而且，紧要关头你们也会在场的，对吧？"}]},{"id":14,"order":14,"actions":[{"uid":"410401201:14:1","speaker":"Kirito","text":"Totally!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"完全可以！"}]},{"id":15,"order":15,"actions":[{"uid":"410401201:15:1","speaker":"Seven","text":"Alllright, then let's do this!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"好吧，那就开始吧！"},{"uid":"410401201:15:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:15:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":16,"order":16,"actions":[{"uid":"410401201:16:1","speaker":"Alice","text":"Eugeo, Kirito! Where were you?!\nThings are getting heated over\nhere!","pose":105401012,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"尤吉欧，桐人！当时你在哪里？！这里的事情正在变得激烈！"},{"uid":"410401201:16:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":17,"order":17,"actions":[{"uid":"410401201:17:1","speaker":"Kirito","text":"Sorry! We had to prep everything!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对不起！我们必须准备好一切！"},{"uid":"410401201:17:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410401201:18:1","speaker":"Alice","text":"Prep what?!","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"准备什么？！"},{"uid":"410401201:18:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":19,"order":19,"actions":[{"uid":"410401201:19:1","speaker":"???","text":"Siiiiiilent Niiiiight...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"平——安——夜——……"}]},{"id":20,"order":20,"actions":[{"uid":"410401201:20:1","speaker":"Alice","text":"Are they...singing?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们……在唱歌吗？"}]},{"id":21,"order":21,"actions":[{"uid":"410401201:21:1","speaker":"Asuna","text":"There we go! The carolers have\nentered the fray! If we're right,\nthe monsters will...","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"来啦！颂歌者已加入战斗！如果我们是对的，怪物就会..."},{"uid":"410401201:21:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410401201:22:1","speaker":"Monster","text":"G-GrARkkK!! GrrrAAGkk!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"G-GrARkkK！！咕咕咕！！"}]},{"id":23,"order":23,"actions":[{"uid":"410401201:23:1","speaker":"Eugeo","text":"Hey, it's hurting them!","pose":10530208,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"哎呀，害他们了！"},{"uid":"410401201:23:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":24,"order":24,"actions":[{"uid":"410401201:24:1","speaker":"Kirito","text":"Awesome, we were right!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"太棒了，我们是对的！"},{"uid":"410401201:24:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":25,"order":25,"actions":[{"uid":"410401201:25:1","speaker":"Kirito","text":"Hit 'em now, while they're\ndefenseless!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"趁他们毫无防备的时候，攻击他们吧！"}]},{"id":26,"order":26,"actions":[{"uid":"410401201:26:1","speaker":"Eugeo","text":"Y-Yeah!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是、是啊！"},{"uid":"410401201:26:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":27,"order":27,"actions":[{"uid":"410401201:27:1","speaker":"Kirito","text":"Phew... We managed to reach town\nsafe and sound.","pose":10011505,"background":"bg_event_christmas_town","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呼……我们平安抵达小镇了。"},{"uid":"410401201:27:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410401201:28:1","speaker":"Asuna","text":"Safe, sound, and exhausted...\nWe got attacked a million times\nout there...","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"平安无事，疲惫不堪……外面被袭击了一百万次……"}]},{"id":29,"order":29,"actions":[{"uid":"410401201:29:1","speaker":"Alice","text":"Hmph. It was a trivial task.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哼。这是一项微不足道的任务。"},{"uid":"410401201:29:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":30,"order":30,"actions":[{"uid":"410401201:30:1","speaker":"Eugeo","text":"Yeah, but only because those\ncarolers were backing us up.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是的，但只是因为那些颂歌者在支持我们。"}]},{"id":31,"order":31,"actions":[{"uid":"410401201:31:1","speaker":"Asuna","text":"Hehe, that's right.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，是啊。"},{"uid":"410401201:31:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":32,"order":32,"actions":[{"uid":"410401201:32:1","speaker":"Seven","text":"Nah, it was all thanks to you.\nYou guys kicked butt out there.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯，都是拜你所赐。你们把屁股踢出去了。"},{"uid":"410401201:32:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410401201:33:1","speaker":"Asuna","text":"Seven, how are your carolers\nholding up?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"赛玟，你们的颂歌还好吗？"}]},{"id":34,"order":34,"actions":[{"uid":"410401201:34:1","speaker":"Seven","text":"Everyone's breathing easy and\nfeeling good. They're happy their\nsongs came in handy.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"大家呼吸顺畅，感觉良好。他们很高兴他们的歌曲派上了用场。"}]},{"id":35,"order":35,"actions":[{"uid":"410401201:35:1","speaker":"Seven","text":"We've been getting beat up\nnon-stop lately, so it felt good\nto hit back for a change.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"最近一直被打，所以回击改变的感觉很好。"}]},{"id":36,"order":36,"actions":[{"uid":"410401201:36:1","speaker":"Seven","text":"And now that we know that carols\ncan lay the pain on those beasts,\nthey shouldn't be much trouble.","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"既然我们知道颂歌可以给那些野兽带来痛苦，那么它们应该不会太麻烦。"}]},{"id":37,"order":37,"actions":[{"uid":"410401201:37:1","speaker":"Kirito","text":"Ha ha ha, well, I'm happy\neverything's worked out.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈哈，好吧，我很高兴一切顺利。"}]},{"id":38,"order":38,"actions":[{"uid":"410401201:38:1","speaker":"Seven","text":"Today's the day!\nTime for the final concert!","pose":10130105,"background":"bg_event_christmas_town","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"今天就是今天！最后一场音乐会的时间到了！"},{"uid":"410401201:38:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:38:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410401201:39:1","speaker":"Seven","text":"Alright, people, time to show the\nworld how hard you practiced!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"好了，各位，是时候向世界展示你们有多努力了！"}]},{"id":40,"order":40,"actions":[{"uid":"410401201:40:1","speaker":"Carolers","text":"You got it!!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"颂歌歌手们","text_zh":"你懂了！！"}]},{"id":41,"order":41,"actions":[{"uid":"410401201:41:1","speaker":"Kirito","text":"So, you need us to escort your\ncarolers around again today,\nright?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以今天又需要我们来护送你们的颂歌对吧？"}]},{"id":42,"order":42,"actions":[{"uid":"410401201:42:1","speaker":"Seven","text":"Yup! Today's the last time we're\ndoing this, so we won't need your\nescort services again.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"是啊！今天是我们最后一次这样做，所以我们不再需要您的护送服务。"}]},{"id":43,"order":43,"actions":[{"uid":"410401201:43:1","speaker":"Seven","text":"But seriously, thanks for\neverything. You really saved\nour bacon.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"但是说实话，谢谢你所做的一切。你真的拯救了我们的培根。"}]},{"id":44,"order":44,"actions":[{"uid":"410401201:44:1","speaker":"Asuna","text":"Well, we were happy to help.\nBesides, those monsters were\ntough,","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我们很乐意提供帮助。况且那些怪物也很凶猛，"}]},{"id":45,"order":45,"actions":[{"uid":"410401201:45:1","speaker":"Asuna","text":"but with your carolers debuffing\nthem, they're not that big of a\ndeal.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不过你的颂歌给他们带来了debuff，他们也没什么大不了的。"}]},{"id":46,"order":46,"actions":[{"uid":"410401201:46:1","speaker":"Alice","text":"Asuna, it's still too early to\nbreathe easy. Save it until\nafter today's escort duty.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"亚丝娜，现在松口气还太早。保存到今天的护送任务结束后。"},{"uid":"410401201:46:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":47,"order":47,"actions":[{"uid":"410401201:47:1","speaker":"Asuna","text":"Hehe, that's a good point.\nWill do!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，说得好。会做！"},{"uid":"410401201:47:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:47:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":48,"order":48,"actions":[{"uid":"410401201:48:1","speaker":"Eugeo","text":"We'll be fine! We've held them off\nno problem until now. Today will\nbe a cakewalk.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我们会没事的！到目前为止，我们已经毫无问题地阻止了他们。今天将是小菜一碟。"},{"uid":"410401201:48:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410401201:49:1","speaker":"Kirito","text":"Right, and we've even called in\nthe ultimate bodyguard for backup\ntoday, just in case.","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"对了，今天还请了终极保镖来支援，以防万一。"},{"uid":"410401201:49:2","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401201:49:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":50,"order":50,"actions":[{"uid":"410401201:50:1","speaker":"Seven","text":"Well, that sounds reassuring.\nWho is this mysterious knight\nin shining armor?","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯，听起来让人放心。这位穿着闪亮盔甲的神秘骑士是谁？"},{"uid":"410401201:50:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:50:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":51,"order":51,"actions":[{"uid":"410401201:51:1","speaker":"Arianrhod","text":"Hey, sorry to keep you waiting.","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"嘿，抱歉让您久等了。"}]},{"id":52,"order":52,"actions":[{"uid":"410401201:52:1","speaker":"Asuna","text":"Hey Arianrhod! Oh wow, you brought\nall of the new KoB members too!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嘿阿里安罗德！哇喔，KoB的新成员都被你带来了！"},{"uid":"410401201:52:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:52:3","speaker":"Seven","text":"","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":53,"order":53,"actions":[{"uid":"410401201:53:1","speaker":"Arianrhod","text":"Hah, sort of. We've disbanded the\nKoB, if you recall.","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"哈，差不多吧。如果你还记得的话，我们已经解散了 KoB。"}]},{"id":54,"order":54,"actions":[{"uid":"410401201:54:1","speaker":"Arianrhod","text":"Still, we've teamed up again for\nthis escort quest of yours.","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"不过，我们还是再次联手完成你的护送任务。"}]},{"id":55,"order":55,"actions":[{"uid":"410401201:55:1","speaker":"KoB Guild Member","text":"Our swords are always yours to\ncommand, Commander! Let's show\n'em what the new KoB is made of!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"KoB公会会员","text_zh":"我们的剑永远由您指挥，指挥官！让我们向他们展示新的 KoB 是由什么组成的！"}]},{"id":56,"order":56,"actions":[{"uid":"410401201:56:1","speaker":"Arianrhod","text":"I thought I told you, I'm not\nyour commander anymore!\nOh, never mind...","pose":10560106,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"我想我已经告诉过你了，我不再是你的指挥官了！哦，别介意..."}]},{"id":57,"order":57,"actions":[{"uid":"410401201:57:1","speaker":"Kirito","text":"Seven, Arianrhod and her friends\nhere are all first-class tanks.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"赛玟、阿里安罗德和她的朋友们都是一流坦克。"},{"uid":"410401201:57:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:57:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410401201:58:1","speaker":"Asuna","text":"And they're all good people,\nand super reliable! Do you\nmind if they join us today?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"而且都是好人，超级靠谱！你介意他们今天加入我们吗？"}]},{"id":59,"order":59,"actions":[{"uid":"410401201:59:1","speaker":"Seven","text":"I've got no reason to say no!\nThe pay's not changing though, so\nyour cut's going down. That cool?","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我没有理由拒绝！不过工资没有变化，所以你的提成会减少。这么酷吗？"},{"uid":"410401201:59:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410401201:60:1","speaker":"Arianrhod","text":"Please, no payment is necessary.\nWe all owe Kirito and Asuna some\npayback for all their help...","pose":10560102,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"拜托，无需付款。我们都欠桐人和亚丝娜一些回报，感谢他们的帮助......"}]},{"id":61,"order":61,"actions":[{"uid":"410401201:61:1","speaker":"Arianrhod","text":"Besides, it's Christmas! We can't\nlet some foul knaves interfere\nwith a group of innocent carolers!","pose":10560105,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"而且，今天是圣诞节！我们不能让一些恶棍干扰一群无辜的颂歌者！"}]},{"id":62,"order":62,"actions":[{"uid":"410401201:62:1","speaker":"Seven","text":"You sure? I'd feel pretty bad\nmaking you work for free...","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你确定吗？让你免费工作我会感觉很糟糕......"},{"uid":"410401201:62:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:62:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":63,"order":63,"actions":[{"uid":"410401201:63:1","speaker":"Arianrhod","text":"Hmm... How about this?\nWe're even, as long as you\nlet us listen to your concert.","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"嗯……这个怎么样？只要你让我们听你的演唱会，我们就扯平了。"}]},{"id":64,"order":64,"actions":[{"uid":"410401201:64:1","speaker":"Arianrhod","text":"You're all fine with that, right?","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"你没意见吧？"}]},{"id":65,"order":65,"actions":[{"uid":"410401201:65:1","speaker":"KoB Guild Member","text":"You bet we are, boss!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"KoB公会会员","text_zh":"你敢打赌，我们是，首领！"}]},{"id":66,"order":66,"actions":[{"uid":"410401201:66:1","speaker":"Seven","text":"Great! The deal is sealed,\nno takebacks allowed!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"太棒了！交易已完成，不允许撤回！"},{"uid":"410401201:66:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:66:3","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":67,"order":67,"actions":[{"uid":"410401201:67:1","speaker":"Eugeo","text":"Hehe, we have some strong allies\nat our side today, huh, Alice?","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"呵呵，今天我们身边有一些强大的盟友吧，爱丽丝？"},{"uid":"410401201:67:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":68,"order":68,"actions":[{"uid":"410401201:68:1","speaker":"Alice","text":"Apparently so. Today is our final\njourney with these holy bards.\nLet us pray all goes well.","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"原来如此。今天是我们与这些神圣吟游诗人的最后旅程。让我们祈祷一切顺利。"}]},{"id":69,"order":69,"actions":[{"uid":"410401201:69:1","speaker":"Monster","text":"Grawwrgh!!","pose":1,"background":"bg_18_mountain_snow","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"},{"uid":"410401201:69:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:69:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:69:4","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410401201:70:1","speaker":"Kirito","text":"Annnd that was quick.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"安恩，很快。"}]},{"id":71,"order":71,"actions":[{"uid":"410401201:71:1","speaker":"Arianrhod","text":"Men, to your positions! Do not let\nthese monsters near our charges!","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"各位，各就各位！不要让这些怪物靠近我们的攻击！"},{"uid":"410401201:71:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:71:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410401201:72:1","speaker":"KoB Guild Member","text":"Yes, Commander!","pose":3,"background":"","item":"","illustration":"","speaker_zh":"KoB公会会员","text_zh":"是，指挥官！"}]},{"id":73,"order":73,"actions":[{"uid":"410401201:73:1","speaker":"Asuna","text":"Hehe, disbanded or not, they\nfight like a true guild!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，解散与否，他们就像一个真正的公会一样战斗！"},{"uid":"410401201:73:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:73:3","speaker":"Seven","text":"","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":74,"order":74,"actions":[{"uid":"410401201:74:1","speaker":"Kirito","text":"I'm just glad they're on our side!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我很高兴他们站在我们这边！"}]},{"id":75,"order":75,"actions":[{"uid":"410401201:75:1","speaker":"Alice","text":"Hyaaah!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哈啊！"},{"uid":"410401201:75:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401201:75:3","speaker":"Arianrhod","text":"","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":""}]},{"id":76,"order":76,"actions":[{"uid":"410401201:76:1","speaker":"Eugeo","text":"Rrrraaagh!!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"呜呜！！"}]},{"id":77,"order":77,"actions":[{"uid":"410401201:77:1","speaker":"Monster","text":"Grraaawrrr!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":78,"order":78,"actions":[{"uid":"410401201:78:1","speaker":"Alice","text":"...","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":79,"order":79,"actions":[{"uid":"410401201:79:1","speaker":"Eugeo","text":"Alice...","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝..."}]},{"id":80,"order":80,"actions":[{"uid":"410401201:80:1","speaker":"Alice","text":"Yes, I've noticed too.\nSomething's different.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是的，我也注意到了。有些东西不一样了。"}]},{"id":81,"order":81,"actions":[{"uid":"410401201:81:1","speaker":"Kirito","text":"What's going on, you two?!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你们两个这是怎么回事？！"},{"uid":"410401201:81:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:81:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":82,"order":82,"actions":[{"uid":"410401201:82:1","speaker":"Alice","text":"Take a close look at this\nmonstrous host, Kirito.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"仔细看看这个怪物主机，桐人。"},{"uid":"410401201:82:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401201:82:3","speaker":"Arianrhod","text":"","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":""}]},{"id":83,"order":83,"actions":[{"uid":"410401201:83:1","speaker":"Kirito","text":"Hmm...? Wait a sec, there's way\nmore than usual!","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……？等一下，比平常多得多！"},{"uid":"410401201:83:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:83:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":84,"order":84,"actions":[{"uid":"410401201:84:1","speaker":"Eugeo","text":"It might be more accurate to say\nthey've increased their numbers\nto match ours...","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"也许更准确的说法是他们增加了数量来与我们匹配......"},{"uid":"410401201:84:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:84:3","speaker":"Arianrhod","text":"","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":""}]},{"id":85,"order":85,"actions":[{"uid":"410401201:85:1","speaker":"Asuna","text":"You're right... But...why?\nAlso, how?","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你说得对……但是……为什么？还有，怎么样？"},{"uid":"410401201:85:2","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""},{"uid":"410401201:85:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":86,"order":86,"actions":[{"uid":"410401201:86:1","speaker":"Seven","text":"In most cases, the system ups the\nenemy count automatically to\nmatch party size...","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"大多数情况下，系统会自动增加敌人数量以匹配队伍规模..."}]},{"id":87,"order":87,"actions":[{"uid":"410401201:87:1","speaker":"Seven","text":"Buuut you don't think it's that\nsimple this time, do you?","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"但是你觉得这次没那么简单吧？"}]},{"id":88,"order":88,"actions":[{"uid":"410401201:88:1","speaker":"Kirito","text":"No way. These attacks are\ndefinitely planned. Someone's\norchestrating this, for certain.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不行。这些袭击绝对是有计划的。肯定有人在策划这一切。"}]},{"id":89,"order":89,"actions":[{"uid":"410401201:89:1","speaker":"Kirito","text":"But...who?","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是……谁？"}]},{"id":90,"order":90,"actions":[{"uid":"410401201:90:1","speaker":"Alice","text":"I sense a powerful aura from\nthe western enemy ranks.","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我从西方敌军的队伍中感受到了一股强大的气息。"},{"uid":"410401201:90:2","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""},{"uid":"410401201:90:3","speaker":"Arianrhod","text":"","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410401201:91:1","speaker":"Alice","text":"I assume it's the enemy\nringleader.","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我猜是敌方头目。"}]},{"id":92,"order":92,"actions":[{"uid":"410401201:92:1","speaker":"Kirito","text":"Aha, that way!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊哈，那边！"},{"uid":"410401201:92:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:92:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410401201:93:1","speaker":"Monster","text":"Grawwwgh!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":94,"order":94,"actions":[{"uid":"410401201:94:1","speaker":"Kirito","text":"Damn... They aren't going to make\nthis easy on us!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可恶……他们不会轻易放过我们的！"}]},{"id":95,"order":95,"actions":[{"uid":"410401201:95:1","speaker":"Arianrhod","text":"HrrraaaaaGGGH!!","pose":10560101,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"哈哈哈哈！！"},{"uid":"410401201:95:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:95:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":96,"order":96,"actions":[{"uid":"410401201:96:1","speaker":"Monster","text":"Grawk?!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"格劳克？！"}]},{"id":97,"order":97,"actions":[{"uid":"410401201:97:1","speaker":"Arianrhod","text":"Leave these things to us!\nWe'll protect the carolers!\nNow go! End this!","pose":10560107,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"这些事情就交给我们吧！我们会保护颂歌者！现在走吧！结束这一切吧！"}]},{"id":98,"order":98,"actions":[{"uid":"410401201:98:1","speaker":"Asuna","text":"Thanks, Arianrhod! But are you\nsure you can handle it?!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谢谢阿里安罗德！但你确定你能应付得来吗？！"},{"uid":"410401201:98:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:98:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410401201:99:1","speaker":"Arianrhod","text":"Easily. Besides, this is my chance\nto make up for all the trouble\nI caused you!","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"很容易。而且，这也是我弥补给你带来的麻烦的机会！"},{"uid":"410401201:99:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:99:3","speaker":"Eugeo","text":"","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410401201:100:1","speaker":"Eugeo","text":"Alice and I will stay here to\nhelp. Can you two do this alone?","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"爱丽丝我会留下来帮忙。你们两个可以单独完成这件事吗？"}]},{"id":101,"order":101,"actions":[{"uid":"410401201:101:1","speaker":"Kirito","text":"Of course! Come on, Asuna!\nLet's go!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"当然！加油，亚丝娜！我们走吧！"},{"uid":"410401201:101:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:101:3","speaker":"Seven","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410401201:102:1","speaker":"Asuna","text":"You got it!","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你懂了！"},{"uid":"410401201:102:2","speaker":"キリト","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:102:3","speaker":"セブン","text":"","pose":10130107,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410401201:103:1","speaker":"???","text":"...","pose":20040107,"background":"bg_18_mountain_snow","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."}]},{"id":104,"order":104,"actions":[{"uid":"410401201:104:1","speaker":"Asuna","text":"It's got to be him!","pose":10020901,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"一定是他！"},{"uid":"410401201:104:2","speaker":"Kirito","text":"","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410401201:105:1","speaker":"Kirito","text":"So that's the guy behind all this!","pose":10011501,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"原来这就是幕后黑手！"},{"uid":"410401201:105:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":106,"order":106,"actions":[{"uid":"410401201:106:1","speaker":"???","text":"You've finally come...","pose":20040105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"你终于来了……"}]},{"id":107,"order":107,"actions":[{"uid":"410401201:107:1","speaker":"Asuna","text":"This Cait Sith tamed all these\nmonsters? Seriously?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"这个猫妖驯服了这么多怪物？严重地？"},{"uid":"410401201:107:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410401201:108:1","speaker":"Kirito","text":"I knew it was a player!\nWait a sec, is it a player?\nI...can't tell.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我就知道是玩家！等一下，是玩家吗？我……说不出来。"}]},{"id":109,"order":109,"actions":[{"uid":"410401201:109:1","speaker":"Asuna","text":"Yeah, that outfit makes it really\nhard to say for sure...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是啊，这身衣服真的很难说……"},{"uid":"410401201:109:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410401201:110:1","speaker":"???","text":"You are right!\nI am...a Cait Sith!!","pose":20040105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"你说得对！我是……猫妖！！"}]},{"id":111,"order":111,"actions":[{"uid":"410401201:111:1","speaker":"Kirito","text":"Yeah...? Not exactly the question,\nbut thanks?","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是吗……？不完全是问题，但是谢谢？"},{"uid":"410401201:111:2","speaker":"Asuna","text":"","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410401201:112:1","speaker":"???","text":"I overheard those white-clad\nwarriors say they would come\nto your aid while I was in town...","pose":20040107,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我在城里的时候，听到那些白衣战士说他们会来帮助你……"}]},{"id":113,"order":113,"actions":[{"uid":"410401201:113:1","speaker":"???","text":"And thus, I called upon a horde of\nmy monstrous allies! And yet, it\nwas not enough to stop you...","pose":20040107,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"于是我召唤了一大群怪物盟友！然而，这还不足以阻止你......"}]},{"id":114,"order":114,"actions":[{"uid":"410401201:114:1","speaker":"Asuna","text":"He eavesdropped on the KoB in\ntown? If he can enter a safe zone,\nhe's a player, right...?","pose":10020903,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他偷听镇上的KoB？如果他能进入安全区，他就是玩家，对吧……？"},{"uid":"410401201:114:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410401201:115:1","speaker":"Yui","text":"Daddy! Mommy!","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸！妈妈！"}]},{"id":116,"order":116,"actions":[{"uid":"410401201:116:1","speaker":"Kirito","text":"Yui!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"结衣！"}]},{"id":117,"order":117,"actions":[{"uid":"410401201:117:1","speaker":"Yui","text":"Now that we're this close, I've\nfinally been able to analyze him!\nHe's...not a player!","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"距离这么近了，我终于可以分析他了！他……不是玩家！"}]},{"id":118,"order":118,"actions":[{"uid":"410401201:118:1","speaker":"Kirito","text":"He's not?! Then...what is he?\nAn NPC with an advanced AI?","pose":100115082,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"不是？！那……他是什么？具有先进AI的NPC？"}]},{"id":119,"order":119,"actions":[{"uid":"410401201:119:1","speaker":"Yui","text":"That's correct. He has high-level\ncognitive abilities and system\nprivileges to enter town.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"没错。他拥有高级认知能力和进城的系统特权。"}]},{"id":120,"order":120,"actions":[{"uid":"410401201:120:1","speaker":"Kirito","text":"Seriously? There are NPCs that\ncan do that? I mean, besides you?\nAnd, uh, Alice and Eugeo?","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"认真的吗？有NPC可以做到吗？我是说，除了你之外？还有，呃，爱丽丝和尤吉欧？"}]},{"id":121,"order":121,"actions":[{"uid":"410401201:121:1","speaker":"Yui","text":"If my theory is right, his\npersonal data is based off of--","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"如果我的理论正确的话，他的个人数据是基于——"},{"uid":"410401201:121:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:121:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":122,"order":122,"actions":[{"uid":"410401201:122:1","speaker":"???","text":"Summoning complete! Arise,\nmy monstrous friends! Arise!","pose":20040105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"召唤完成！起来吧，我可怕的朋友们！出现！"}]},{"id":123,"order":123,"actions":[{"uid":"410401201:123:1","speaker":"Monster","text":"Grawwwrrr!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":124,"order":124,"actions":[{"uid":"410401201:124:1","speaker":"Kirito","text":"Oh, come on, how many monsters\ncan this guy summon?!","pose":100115012,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哎哟，这家伙到底能召唤多少只怪物啊！"},{"uid":"410401201:124:2","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:124:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410401201:125:1","speaker":"???","text":"We will meet again, you meddling\nmiscreants!","pose":20040105,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我们又见面了，你们这些多管闲事的坏蛋！"}]},{"id":126,"order":126,"actions":[{"uid":"410401201:126:1","speaker":"Asuna","text":"Hey, he's running away!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"喂，他跑了！"},{"uid":"410401201:126:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:126:3","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410401201:127:1","speaker":"Kirito","text":"Asuna, let him go! We need to\ndeal with these guys right now!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"亚丝娜，放开他！我们现在需要对付这些家伙！"}]},{"id":128,"order":128,"actions":[{"uid":"410401201:128:1","speaker":"Asuna","text":"Y-Yeah, but... Oh, fine!","pose":100209072,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"是、是啊，但是……哦，好吧！"},{"uid":"410401201:128:2","speaker":"キリト","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:128:3","speaker":"ユイ","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410401201:129:1","speaker":"Seven","text":"Hey, they're back!\nYoohoo! Kirito! Asuna!","pose":10130108,"background":"bg_18_mountain_snow","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嘿，他们回来了！哟呼！ 桐人！ 亚丝娜！"}]},{"id":130,"order":130,"actions":[{"uid":"410401201:130:1","speaker":"Kirito","text":"Is everyone okay?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"大家还好吗？"},{"uid":"410401201:130:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410401201:131:1","speaker":"Arianrhod","text":"Of course. We slew every last\nmonster lurking in this area.","pose":10560105,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"当然。我们杀死了潜伏在该地区的所有怪物。"},{"uid":"410401201:131:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:131:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":132,"order":132,"actions":[{"uid":"410401201:132:1","speaker":"Alice","text":"And you? Did you catch our\nmysterious foe?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你呢？你抓住我们神秘的敌人了吗？"}]},{"id":133,"order":133,"actions":[{"uid":"410401201:133:1","speaker":"Asuna","text":"We found a guy in a black cloak,\nbut he summoned a bunch more\nmonsters and ran away.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们发现了一个黑斗篷的家伙，但是他又召唤了一堆怪物然后逃跑了。"},{"uid":"410401201:133:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:133:3","speaker":"Seven","text":"","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410401201:134:1","speaker":"Eugeo","text":"I see... Well, I'm just glad you\ntwo are okay.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我明白了……好吧，我很高兴你们两个没事。"},{"uid":"410401201:134:2","speaker":"Arianrhod","text":"","pose":10560105,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":""},{"uid":"410401201:134:3","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":135,"order":135,"actions":[{"uid":"410401201:135:1","speaker":"Seven","text":"Yeah! Besides, if he comes back,\nwe'll just beat the stuffing out\nof him again!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"是啊！再说了，他要是回来了，我们就再把他打个稀巴烂！"},{"uid":"410401201:135:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:135:3","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":136,"order":136,"actions":[{"uid":"410401201:136:1","speaker":"Kirito","text":"Y-Yeah, I guess...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是、是啊，我想……"}]},{"id":137,"order":137,"actions":[{"uid":"410401201:137:1","speaker":"Arianrhod","text":"Excellent. Now, let us resume our\njourney.","pose":10560105,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"非常好。现在，让我们继续我们的旅程。"},{"uid":"410401201:137:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:137:3","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":138,"order":138,"actions":[{"uid":"410401201:138:1","speaker":"Seven","text":"Siiiiiilent Niiiiight...","pose":10130104,"background":"bg_12_church_room","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"平——安——夜——……"}]},{"id":139,"order":139,"actions":[{"uid":"410401201:139:1","speaker":"Carolers","text":"Siiiiiilent Niiiiight...","pose":3,"background":"","item":"","illustration":"","speaker_zh":"颂歌歌手们","text_zh":"平——安——夜——……"}]},{"id":140,"order":140,"actions":[{"uid":"410401201:140:1","speaker":"Arianrhod","text":"Ahhh... What an angelic sound...","pose":10560104,"background":"","item":"","illustration":"","speaker_zh":"阿里安罗德","text_zh":"啊啊……天使般的声音……"},{"uid":"410401201:140:2","speaker":"Alice","text":"","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""},{"uid":"410401201:140:3","speaker":"Eugeo","text":"","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":141,"order":141,"actions":[{"uid":"410401201:141:1","speaker":"Alice","text":"I have to say, I think I despise\nthe gaudy decorations of this\nChristmas of yours...","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不得不说，我觉得我很鄙视你这个圣诞节的华丽装饰……"}]},{"id":142,"order":142,"actions":[{"uid":"410401201:142:1","speaker":"Alice","text":"But I shall never forget the\nheavenly notes of these carols...","pose":10540104,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但我永远不会忘记这些颂歌的天堂般的音符......"}]},{"id":143,"order":143,"actions":[{"uid":"410401201:143:1","speaker":"Eugeo","text":"And neither will I... They really\ndo make you feel all warm and\nhappy inside...","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也不会……他们确实让你内心感到温暖和幸福……"}]},{"id":144,"order":144,"actions":[{"uid":"410401201:144:1","speaker":"Asuna","text":"Hehe, it looks like Seven and her\ncarolers have touched our friends'\nhearts.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，看来赛玟和她的歌声感动了朋友们的心。"},{"uid":"410401201:144:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":145,"order":145,"actions":[{"uid":"410401201:145:1","speaker":"Kirito","text":"Ha ha, yeah, they're really into\nit. I'm glad we were able to get\nthem here safely.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，是的，他们真的很喜欢。我很高兴我们能够将他们安全地带到这里。"}]},{"id":146,"order":146,"actions":[{"uid":"410401201:146:1","speaker":"Asuna","text":"You say that, but you don't look\ntoo happy.","pose":10020909,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你虽然这么说，但看上去不太高兴。"}]},{"id":147,"order":147,"actions":[{"uid":"410401201:147:1","speaker":"Kirito","text":"Well...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……"}]},{"id":148,"order":148,"actions":[{"uid":"410401201:148:1","speaker":"Asuna","text":"That mysterious cloaked Cait Sith\nis still on your mind, huh?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那个神秘斗篷猫妖你还记得吗？"}]},{"id":149,"order":149,"actions":[{"uid":"410401201:149:1","speaker":"Kirito","text":"Yeah... I want to talk to Yui\nabout him somewhere quiet...\nLet's head outside, Asuna.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯……我想找个安静的地方和结衣谈谈他的事……我们出去吧，亚丝娜。"}]},{"id":150,"order":150,"actions":[{"uid":"410401201:150:1","speaker":"Kirito","text":"Or would you rather stay here\nuntil they're finished?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"或者你宁愿留在这里直到他们完成？"}]},{"id":151,"order":151,"actions":[{"uid":"410401201:151:1","speaker":"Asuna","text":"No, it's okay. They're almost\ndone, anyway. Let's have this\ntalk.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不用了，没关系。无论如何，他们快完成了。我们来谈谈这个吧。"}]},{"id":152,"order":152,"actions":[{"uid":"410401201:152:1","speaker":"Yui","text":"That black-cloaked Cait Sith is\nmost definitely an enemy NPC.","pose":20090207,"background":"bg_event_tree_snow_christmas","item":"","illustration":"","speaker_zh":"结衣","text_zh":"那个黑斗篷猫妖绝对是敌人NPC。"},{"uid":"410401201:152:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410401201:152:3","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":153,"order":153,"actions":[{"uid":"410401201:153:1","speaker":"Kirito","text":"Yeah, his \"I am a Cait Sith\"\nstatement of the obvious\nwas totally an NPC line.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，他的“我是猫妖”这句明显的话完全就是NPC的台词。"}]},{"id":154,"order":154,"actions":[{"uid":"410401201:154:1","speaker":"Yui","text":"If I were to hazard a guess, I'd\nsay that he was created as part\nof the Divine Object quest.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"如果我大胆猜测的话，我会说他是作为神器任务的一部分被创建的。"}]},{"id":155,"order":155,"actions":[{"uid":"410401201:155:1","speaker":"Yui","text":"Likely, Cardinal decided the quest\nneeded a specific antagonist for\nyou to face.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"很可能，卡迪纳尔决定该任务需要你面对一个特定的对手。"}]},{"id":156,"order":156,"actions":[{"uid":"410401201:156:1","speaker":"Yui","text":"And I have bad news: the personal\ndata used to generate him is\nbased off of—","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我有一个坏消息：用于生成他的个人数据基于——"}]},{"id":157,"order":157,"actions":[{"uid":"410401201:157:1","speaker":"Kirito","text":"Yeah, I know.\nEugeo and Alice, right?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯，我知道。 尤吉欧和爱丽丝，对吧？"}]},{"id":158,"order":158,"actions":[{"uid":"410401201:158:1","speaker":"Asuna","text":"What?! No way!","pose":100209082,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什么？！决不！"}]},{"id":159,"order":159,"actions":[{"uid":"410401201:159:1","speaker":"Yui","text":"So you noticed, Daddy?","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸，你注意到了吗？"}]},{"id":160,"order":160,"actions":[{"uid":"410401201:160:1","speaker":"Kirito","text":"It was an educated guess.\nI thought to myself: why, and how,\ndid Cardinal create this NPC?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这是一个有根据的猜测。我心想：卡迪纳尔为什么、如何创造出这个NPC？"}]},{"id":161,"order":161,"actions":[{"uid":"410401201:161:1","speaker":"Kirito","text":"Then it all clicked. Bad guy boss\ncharacter for the epic Divine\nObject quest. But where to get...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"然后就一切顺利了。坏人首领角色，用于史诗般的神圣物品任务。但哪里可以得到..."}]},{"id":162,"order":162,"actions":[{"uid":"410401201:162:1","speaker":"Kirito","text":"...the template? Well, with Alice\nand Eugeo on our side, it needed\nan equally smart and badass enemy.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……模板？好吧，有了爱丽丝和尤吉欧站在我们这边，它需要一个同样聪明和强大的敌人。"}]},{"id":163,"order":163,"actions":[{"uid":"410401201:163:1","speaker":"Kirito","text":"So Cardinal took all the data it'd\ngathered on the two and used that\nto generate an advanced AI NPC.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以卡迪纳尔收集了两者的所有数据，并用它来生成高级AI NPC。"}]},{"id":164,"order":164,"actions":[{"uid":"410401201:164:1","speaker":"Kirito","text":"In other words, it made a big,\nsmart, scary boss for us.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也就是说，它为我们制作了一个又大又聪明又吓人的首领。"}]},{"id":165,"order":165,"actions":[{"uid":"410401201:165:1","speaker":"Asuna","text":"Why did it use data from both\nAlice AND Eugeo?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"为什么同时使用爱丽丝和尤吉欧的数据？"}]},{"id":166,"order":166,"actions":[{"uid":"410401201:166:1","speaker":"Kirito","text":"Balance. It needed someone as\ntough as both of them put together\nto even the playing field.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"余额。它需要像他们两个一样坚强的人来平衡竞争环境。"}]},{"id":167,"order":167,"actions":[{"uid":"410401201:167:1","speaker":"Yui","text":"I agree with your assessment of\nthe situation, Daddy.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我同意你对情况的评估，爸爸。"}]},{"id":168,"order":168,"actions":[{"uid":"410401201:168:1","speaker":"Yui","text":"I can almost guarantee that he'll\nbe back to cause trouble as you\nwork on the Divine Object quest.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"我几乎可以保证，当你完成神器任务时，他会回来制造麻烦。"}]},{"id":169,"order":169,"actions":[{"uid":"410401201:169:1","speaker":"Yui","text":"And unlike most monsters, we won't\nbe able to predict how or when\nhe'll move to oppose us.","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"与大多数怪物不同，我们无法预测他将如何或何时移动来对抗我们。"}]},{"id":170,"order":170,"actions":[{"uid":"410401201:170:1","speaker":"Kirito","text":"Yeah...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……"}]},{"id":171,"order":171,"actions":[{"uid":"410401201:171:1","speaker":"Asuna","text":"So we have to fight a ridiculously\nsmart NPC? This sounds like it'll\nbe worse than PvP...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"所以我们要和一个聪明到离谱的NPC战斗？这听起来会比 PvP 更糟糕......"}]},{"id":172,"order":172,"actions":[{"uid":"410401201:172:1","speaker":"Kirito","text":"Let's keep this a secret from\nAlice and Eugeo for now.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"暂时对爱丽丝和尤吉欧保密吧。"}]},{"id":173,"order":173,"actions":[{"uid":"410401201:173:1","speaker":"Kirito","text":"I mean, if we tried to explain it,\ntheir heads would probably\nexplode.","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我的意思是，如果我们试图解释的话，他们的头可能会爆炸。"}]},{"id":174,"order":174,"actions":[{"uid":"410401201:174:1","speaker":"Asuna","text":"We definitely don't want that...\nStill, Cardinal really likes\nmaking our lives difficult.","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我们绝对不希望这样……不过，卡迪纳尔真的很喜欢让我们的生活变得困难。"}]},{"id":175,"order":175,"actions":[{"uid":"410401201:175:1","speaker":"Kirito","text":"Seriously. It's picked up some\nreaaally annoying tricks lately.","pose":10011506,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"说真的。最近它发现了一些非常烦人的技巧。"},{"uid":"410401201:175:2","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:175:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":176,"order":176,"actions":[{"uid":"410401201:176:1","speaker":"Seven","text":"There you are!! I've been looking\nall over for you two lovebirds!","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"给你！！我一直在寻找你们两个爱情鸟！"}]},{"id":177,"order":177,"actions":[{"uid":"410401201:177:1","speaker":"Kirito","text":"Oh, hey Seven.\nIs the concert over already?","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"噢，嘿赛玟。演唱会已经结束了吗？"},{"uid":"410401201:177:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:177:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":178,"order":178,"actions":[{"uid":"410401201:178:1","speaker":"Seven","text":"Yeah! Wait... Waaaiiit a second...\nI know what's going on here!","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"是啊！等等……等一下……我知道这是怎么回事！"}]},{"id":179,"order":179,"actions":[{"uid":"410401201:179:1","speaker":"Seven","text":"You two snuck out of my concert\nto go find a romantic Christmas\ncorner to make out in, didn't you?","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"你们两个偷偷溜出我的演唱会，去寻找一个浪漫的圣诞角落亲热，是吗？"}]},{"id":180,"order":180,"actions":[{"uid":"410401201:180:1","speaker":"Asuna","text":"N-No! We were doing nothing\nof the sort!","pose":100209101,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"不、不！我们什么也没做！"},{"uid":"410401201:180:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:180:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":181,"order":181,"actions":[{"uid":"410401201:181:1","speaker":"Seven","text":"Hehe, I'm just teasin' ya.\nOh! By the way!","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"呵呵，逗你玩的。哦！顺便一提！"}]},{"id":182,"order":182,"actions":[{"uid":"410401201:182:1","speaker":"Seven","text":"I wanted to give you guys\nsomething besides cold hard Yuld\nto thank you for all your help.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"除了冷硬的Yuld之外，我还想送点东西来感谢你们的帮助。"}]},{"id":183,"order":183,"actions":[{"uid":"410401201:183:1","speaker":"Kirito","text":"What, for reals?\nI love free stuff!","pose":10011503,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么，真的吗？我喜欢免费的东西！"},{"uid":"410401201:183:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:183:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":184,"order":184,"actions":[{"uid":"410401201:184:1","speaker":"Seven","text":"Ta-dah! What do you think?","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"哒哒！你怎么认为？"}]},{"id":185,"order":185,"actions":[{"uid":"410401201:185:1","speaker":"Asuna","text":"Wait, is that what I think it is?","pose":10020911,"background":"","item":"item_event_sacred_treasure","illustration":"","speaker_zh":"亚丝娜","text_zh":"等等，是我想的那样吗？"},{"uid":"410401201:185:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:185:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":186,"order":186,"actions":[{"uid":"410401201:186:1","speaker":"Kirito","text":"That shape... That color...\nIt's a Divine Object!!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那个形状……那个颜色……是神器！！"},{"uid":"410401201:186:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":187,"order":187,"actions":[{"uid":"410401201:187:1","speaker":"Seven","text":"Huh? THIS is one of those things\nyou guys have been looking for?!","pose":10130108,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"啊？这是你们一直在寻找的东西之一？！"}]},{"id":188,"order":188,"actions":[{"uid":"410401201:188:1","speaker":"Asuna","text":"Seven, where did you find this?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"赛玟，你在哪里找到的？"},{"uid":"410401201:188:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410401201:188:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":189,"order":189,"actions":[{"uid":"410401201:189:1","speaker":"Seven","text":"Well, when we got here, we went\ndown into the church basement for\nsome rehearsing, and there it was.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯，当我们到达这里时，我们到教堂地下室排练，就在那里。"}]},{"id":190,"order":190,"actions":[{"uid":"410401201:190:1","speaker":"Seven","text":"It had this super-cool, ancient,\nholy artifact vibe, so I thought\nit might be rare.","pose":10130105,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"有种超酷、远古、圣器的感觉，所以我觉得可能很少见。"}]},{"id":191,"order":191,"actions":[{"uid":"410401201:191:1","speaker":"Seven","text":"I had no idea what it was, but it\nlooked valuable, so...yoink!","pose":10130102,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"我不知道那是什么，但看起来很有价值，所以……哎呀！"}]},{"id":192,"order":192,"actions":[{"uid":"410401201:192:1","speaker":"Kirito","text":"Ha ha, awesome! Random luck for\nthe win! I bet Alice and Eugeo\nwill be ecstatic!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哈哈，厉害了！随机运气获胜！我打赌爱丽丝和尤吉欧一定会欣喜若狂！"},{"uid":"410401201:192:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:192:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":193,"order":193,"actions":[{"uid":"410401201:193:1","speaker":"Seven","text":"Well, I'm glad you're happy.\nHeh, escorting us around turned\nout to be super profitable, huh?","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"嗯，我很高兴你幸福。呵呵，原来陪着我们是超赚钱的啊？"}]},{"id":194,"order":194,"actions":[{"uid":"410401201:194:1","speaker":"Kirito","text":"Apparently, yeah!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"看来是啊！"},{"uid":"410401201:194:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:194:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":195,"order":195,"actions":[{"uid":"410401201:195:1","speaker":"Asuna","text":"Ahaha, yay! And we got some info\non a scary new bad guy too!","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊哈哈，耶！我们还得到了一些关于一个可怕的新坏人的信息！"},{"uid":"410401201:195:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":196,"order":196,"actions":[{"uid":"410401201:196:1","speaker":"Seven","text":"Cool, well...me and my carolers\nare about to go out to celebrate\nour musical victory! Want to come?","pose":10130104,"background":"","item":"","illustration":"","speaker_zh":"赛玟","text_zh":"酷，好吧……我和我的颂歌者就要出去庆祝我们的音乐胜利了！想来吗？"}]},{"id":197,"order":197,"actions":[{"uid":"410401201:197:1","speaker":"Kirito","text":"Yeah!","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯！"},{"uid":"410401201:197:2","speaker":"Yui","text":"","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410401201:197:3","speaker":"Asuna","text":"","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":198,"order":198,"actions":[{"uid":"410401201:198:1","speaker":"Asuna","text":"Hehe, this is going to be a fun\nnight!","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呵呵，这会是一个有趣的夜晚！"}]}]};
